      res.writeHead(200, { "Content-Type": "image/x-icon", "Cache-Control": "public, max-age=86400" });
      res.end(ico);
    } catch {
      res.writeHead(404);
      res.end();
    }
    return;
  }

  // ── GET /status — JSON state ──────────────────────────────────────────────
  if (req.method === "GET" && url.pathname === "/status") {
    res.writeHead(200, { "Content-Type": "application/json", "Cache-Control": "no-store" });
    res.end(JSON.stringify({
      version:     BUILD_VERSION,
      status:      state.status,
      runId:       state.runId,
      params:      state.params,
      startedAt:   state.startedAt,
      finishedAt:  state.finishedAt,
      exitCode:    state.exitCode,
      pid:         state.pid,
      bufferedLogLines: state.logLines.length,
      progress:    state.progress,
    }));
    return;
  }

  // ── GET /logs — plain-text log tail ──────────────────────────────────────
  if (req.method === "GET" && url.pathname === "/logs") {
    const n = Math.min(parseInt(url.searchParams.get("n") || "100", 10), MAX_LOG_LINES);
    res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
    res.end(state.logLines.slice(-n).join("\n"));
    return;
  }

  // ── POST /run — start a run ───────────────────────────────────────────────
  if (req.method === "POST" && url.pathname === "/run") {
    if (state.status === "running") {
      res.writeHead(409, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "A run is already in progress", runId: state.runId }));
      return;
    }

    let body = "";
    req.on("data", (chunk) => (body += chunk));
    req.on("end", () => {
      let params = {};
      try {
        if (body.trim()) params = JSON.parse(body);
      } catch {
        res.writeHead(400, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: "Invalid JSON body" }));
        return;
      }

      try {
        startRun(params);
      } catch (err) {
        res.writeHead(400, { "Content-Type": "application/json" });
        res.end(JSON.stringify({
          error: "Cannot start run",
          message: err instanceof Error ? err.message : String(err),
          validTests: Object.keys(ENTRYPOINTS),
        }));
        return;
      }
      res.writeHead(202, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ message: "Run started", runId: state.runId, status: "running" }));
    });
    return;
  }

  // ── POST /stop — kill the running process ──────────────────────────────────
  if (req.method === "POST" && url.pathname === "/stop") {
    if (state.status !== "running" || !currentProcess) {
      res.writeHead(409, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "No run in progress" }));
      return;
    }
    const pid = currentProcess.pid;
    appendLog(`[STOP] Killing process ${pid} via POST /stop`);
    currentProcess.kill("SIGTERM");
    setTimeout(() => {
      if (currentProcess) currentProcess.kill("SIGKILL");
    }, 5000);
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ message: "Stop signal sent", pid }));
    return;
  }

  // ── GET /files — list files under /app/runs/ ─────────────────────────────
  // ── GET /files/<name> — fetch a single file under /app/runs/ ──────────────
  // Used to retrieve per-cell results-*.json files when an image lacks the
  // aws CLI / S3 push didn't run. Read-only, scoped to /app/runs/, no
  // traversal — anything containing ".." or a leading "/" is rejected.
  if (req.method === "GET" && url.pathname.startsWith("/files")) {
    const RUNS_DIR = "/app/runs";
    const tail = url.pathname.replace(/^\/files\/?/, "");
    if (tail === "") {
      try {
        const entries = readdirSync(RUNS_DIR)
          .filter((f) => !f.startsWith("."))
          .map((f) => {
            try {
              const st = statSync(path.join(RUNS_DIR, f));
              return { name: f, size: st.size, mtime: st.mtime.toISOString() };
            } catch {
              return null;
            }
          })
          .filter(Boolean);
        res.writeHead(200, { "Content-Type": "application/json", "Cache-Control": "no-store" });
        res.end(JSON.stringify({ dir: RUNS_DIR, files: entries }));
      } catch (e) {
        res.writeHead(500, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: "list_failed", message: e.message }));
      }
      return;
    }
    if (tail.includes("..") || tail.includes("/") || tail.includes("\\")) {
      res.writeHead(400, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Invalid filename" }));
      return;
    }
    const target = path.join(RUNS_DIR, tail);
    try {
      const buf = readFileSync(target);
      const ct = tail.endsWith(".json") ? "application/json" : "text/plain; charset=utf-8";
      res.writeHead(200, { "Content-Type": ct, "Cache-Control": "no-store" });
      res.end(buf);
    } catch (e) {
      res.writeHead(404, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Not found", file: tail, message: e.message }));
    }
    return;
  }

  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "Not found", path: url.pathname }));
});

