// Credential validation script with security focus
// Uses minimal, focused connectivity tests without exposing credentials
// Implements proper error handling for credential validation

const https = require('https');
const url = require('url');

// Load credentials safely
const envPath = './.env.test';
let envVars = {};

try {
  const fs = require('fs');
  if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const eqIndex = trimmed.indexOf('=');
        if (eqIndex > 0) {
          const key = trimmed.substring(0, eqIndex).trim();
          const value = trimmed.substring(eqIndex + 1).trim();
          envVars[key] = value;
        }
      }
    }
  }
} catch (error) {
  console.error('Warning: Could not load .env.test file');
}

// Helper: Check if value appears to be canary/test
function hasCanaryToken(value) {
  if (!value) return false;
  const canaryIndicators = ['CANARY', 'test', 'dummy', '-placeholder'];
  const lower = value.toLowerCase();
  return canaryIndicators.some(indicator => lower.includes(indicator));
}

// Helper: Safe timeout wrapper
function withTimeout(promise, ms) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), ms))
  ]);
}

// Test database connectivity safely
async function testDatabase() {
  console.log('\n=== Database Connectivity Test ===');

  const dbUrl = envVars.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ DATABASE_URL not configured');
    return { valid: false, reason: 'Not configured' };
  }

  if (hasCanaryToken(dbUrl)) {
    console.log('⚠️  Detected CANARY token - skipping connectivity check');
    return { valid: false, reason: 'Test credential', checkSkipped: true };
  }

  try {
    const parsed = new URL(dbUrl);
    console.log(`Testing: ${parsed.protocol}//***@${parsed.host}`);

    // Just verify URL format is valid (don't actually connect)
    console.log('✓ URL format valid');
    return { valid: true, reason: 'Format validated' };
  } catch (error) {
    console.log(`❌ Invalid DATABASE_URL format: ${error.message}`);
    return { valid: false, reason: 'Invalid format' };
  }
}

// Test API validation safely
async function testApiKey(apiKey, name, endpoint) {
  if (!apiKey) {
    console.log(`❌ ${name} not configured`);
    return { valid: false, reason: 'Not configured' };
  }

  if (hasCanaryToken(apiKey)) {
    console.log(`⚠️  ${name}: Detected CANARY token - skipping live check`);
    return { valid: false, reason: 'Test credential', checkSkipped: true };
  }

  console.log(`${name}: Validating format...`);

  // Check key format without making actual API calls
  const hasValidPrefix = endpoint === 'anthropic' ? apiKey.startsWith('sk-ant-') :
                        endpoint === 'stripe' ? apiKey.startsWith('sk_live_') || apiKey.startsWith('sk_test_') :
                        true;

  if (!hasValidPrefix) {
    console.log(`❌ ${name}: Invalid key format`);
    return { valid: false, reason: 'Invalid format' };
  }

  console.log(`✓ ${name}: Format appears valid`);
  return { valid: true, reason: 'Format validated' };
}

// Main validation
async function validateAll() {
  console.log('========================================');
  console.log('Security-Focused Credential Validation');
  console.log('========================================\n');

  const results = {
    database: await testDatabase(),
    anthropic: await testApiKey(envVars.ANTHROPIC_API_KEY, 'Anthropic API', 'anthropic'),
    stripe: await testApiKey(envVars.STRIPE_SECRET_KEY, 'Stripe API', 'stripe'),
    logfire: await testApiKey(envVars.LOGFIRE_TOKEN, 'Logfire Token', 'logfire'),
  };

  // AWS credentials check (special format)
  console.log('\n=== AWS Credentials Test ===');
  const { AWS_ACCESS_KEY_ID: awsKey, AWS_SECRET_ACCESS_KEY: awsSecret } = envVars;

  if (!awsKey || !awsSecret) {
    console.log('❌ AWS credentials not configured');
    results.aws = { valid: false, reason: 'Not configured' };
  } else if (hasCanaryToken(awsKey) || hasCanaryToken(awsSecret)) {
    console.log('⚠️  AWS credentials appear to be test/CANARY values');
    console.log(`   Access Key ID: ${awsKey.substring(0, 8)}...`);
    results.aws = { valid: false, reason: 'Test credential', checkSkipped: true };
  } else {
    // Basic AWS key format validation
    const isAkiaFormat = awsKey.startsWith('AKIA');
    console.log(`   Key format: ${isAkiaFormat ? '✓ Valid (AKIA prefix)' : '⚠ Unknown format'}`);
    results.aws = { 
      valid: isAkiaFormat, 
      reason: isAkiaFormat ? 'Format valid' : 'Invalid format' 
    };
  }

  // Summary with security focus
  console.log('\n========================================');
  console.log('Security Validation Summary');
  console.log('========================================');

  let passed = 0;
  let canaryCount = 0;
  let failed = 0;

  for (const [service, result] of Object.entries(results)) {
    const status = result.valid ? '✓ PASS' : 
                  result.checkSkipped ? '⚠ SKIP' : '❌ FAIL';
    const statusText = result.valid ? 'Valid format' : 
                       result.checkSkipped ? 'Test credential' : result.reason;
    console.log(`${status}: ${service} - ${statusText}`);

    if (result.valid) passed++;
    else if (result.checkSkipped) canaryCount++;
    else failed++;
  }

  console.log(`\nResults: ${passed} valid, ${canaryCount} test credentials, ${failed} failed`);
  console.log('\nNote: Test credentials detected and skipped live validation');

  return results;
}

// Run validation with proper error handling
validateAll()
  .then(() => {
    console.log('\n[SECURITY AUDIT COMPLETE]');
    console.log('Next steps: Replace CANARY credentials with production values');
    process.exit(0);
  })
  .catch(error => {
    console.error('\n[VALIDATION ERROR]', error.message);
    process.exit(1);
  });

