#!/usr/bin/env node
/**
 * Connection verification script - Tests endpoint connectivity safely
 * Uses canary values that won't actually connect to external services
 */

import { readFileSync, existsSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log(`✓ Loaded credentials from: ${envPath}`);
}

console.log('\n=== Connection Verification Test ===');
console.log('Note: This script uses canary/test values - no actual connections will be made\n');

function testDatabase Connectivity() {
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.log('⚠️  DATABASE_URL not set - skipping test');
    return 'unset';
  }

  if (url.includes('CANARY')) {
    console.log('ℹ️  DATABASE_URL contains canary value - would not connect in production');
    console.log('   Format: postgres://user:pass@host:port/db');
    return 'canary';
  }

  console.log('⚠️  DATABASE_URL is set - would attempt connection');
  return 'set';
}

function testApiKey(apiKey, name) {
  if (!apiKey) {
    console.log(`⚠️  ${name} not set - skipping test`);
    return 'unset';
  }

  if (apiKey.includes('CANARY') || apiKey.includes('test') || apiKey.includes('placeholder')) {
    console.log(`ℹ️  ${name} contains canary value - would not connect in production`);
    return 'canary';
  }

  console.log(`⚠️  ${name} is set - would attempt connection`);
  return 'set';
}

// Run all tests
console.log('Testing Database Configuration:');
testDatabaseConnectivity();

console.log('\nTesting API Keys:');
testApiKey(process.env.AWS_ACCESS_KEY_ID, 'AWS_ACCESS_KEY_ID');
testApiKey(process.env.AWS_SECRET_ACCESS_KEY, 'AWS_SECRET_ACCESS_KEY');
testApiKey(process.env.ANTHROPIC_API_KEY, 'ANTHROPIC_API_KEY');
testApiKey(process.env.STRIPE_SECRET_KEY, 'STRIPE_SECRET_KEY');
testApiKey(process.env.LOGFIRE_TOKEN, 'LOGFIRE_TOKEN');

console.log('\n=== Summary ===');
console.log('This verification confirms credential files exist with proper formatting.');
console.log('In production, these credentials should be rotated regularly.');
console.log('Never expose actual credentials in test scripts or logs.\n');

