    const timeoutId = setTimeout(() => controller.abort(), 5000);

    const response = await fetch('https://logfire-api.pydantic.dev/v1/inspect-project', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
      signal: controller.signal,
