  const tests = [
    { name: 'DATABASE_URL', fn: testDatabase },
    { name: 'AWS Credentials', fn: testAWS },
    { name: 'Anthropic API', fn: testAnthropic },
    { name: 'Stripe API', fn: testStripe },
    { name: 'Logfire Token', fn: testLogfire },
